let user = {
  name: "Jeet"
};

console.log(user.name);

user = null;

// The object no longer has a reference from `user`.
// If there are no other references to it,
// it becomes eligible for garbage collection.

let user = {
  name: "Jeet"
};

let anotherReference = user;

user = null;

// The object is still reachable through anotherReference.
// Therefore, it cannot be garbage collected yet.

anotherReference = null;

// Now there may be no references to the object.
