// Example: an interval that is never cleared
const data = new Array(1000000).fill("data");

setInterval(() => {
  console.log(data.length);
}, 1000);

// The interval keeps running and keeps its callback alive.
// The callback references `data`, so `data` cannot be collected
// while that interval remains active.

const button = document.querySelector("button");

function handleClick() {
  console.log("Clicked");
}

button.addEventListener("click", handleClick);

// Later, when the listener is no longer needed:
button.removeEventListener("click", handleClick);

// Removing listeners when they are no longer needed
// helps release unnecessary references.

function createHandler() {
  const largeData = new Array(1000000).fill("data");

  return function () {
    console.log(largeData.length);
  };
}

const handler = createHandler();

// `handler` keeps the closure alive.
// The closure keeps access to `largeData`.

// When the handler is no longer needed:
// handler = null;
// If no other references exist, the closure and captured data
// can eventually become eligible for garbage collection.

const button = document.querySelector("button");

function handleClick() {
  console.log("Clicked");
}

button.addEventListener("click", handleClick);

const intervalId = setInterval(() => {
  console.log("Running...");
}, 1000);

// Cleanup when these resources are no longer needed
button.removeEventListener("click", handleClick);
clearInterval(intervalId);

// Good cleanup prevents unnecessary resources and references
// from staying alive.
